<script setup>
import { onMounted, reactive, ref } from 'vue'; import { useRoomTypesStore } from '../stores/roomTypes';
const store = useRoomTypesStore(); const dialog = ref(false); const form = reactive({ id: null, name: '' });
onMounted(() => store.fetch()); function edit(item) { Object.assign(form, item); dialog.value = true; } function create() { Object.assign(form, { id: null, name: '' }); dialog.value = true; } async function save() { try { await store.save(form); dialog.value = false; } catch {} }
</script>
<template><v-main><v-container><div class="d-flex align-center mb-6"><h1 class="text-h4">Tipos de habitación</h1><v-spacer /><v-btn color="primary" @click="create">Nuevo tipo</v-btn></div><v-alert v-if="store.error" type="error" class="mb-4">{{ store.error }}</v-alert><v-card><v-data-table :headers="[{ title: 'Nombre', key: 'name' }, { title: 'Acciones', key: 'actions', sortable: false }]" :items="store.items" :loading="store.loading"><template #item.actions="{ item }"><v-btn variant="text" color="primary" @click="edit(item)">Editar</v-btn></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="520"><v-card><v-card-title>{{ form.id ? 'Editar tipo' : 'Nuevo tipo' }}</v-card-title><v-card-text><v-text-field v-model="form.name" label="Nombre" autofocus /></v-card-text><v-card-actions><v-spacer /><v-btn @click="dialog = false">Cancelar</v-btn><v-btn color="primary" :loading="store.saving" :disabled="store.saving" @click="save">Guardar</v-btn></v-card-actions></v-card></v-dialog></v-container></v-main></template>
